184	/// Query targeting the synchronizable store for `account`.
185	///
186	/// `Some(true)` (never `None`) so every operation addresses exactly one store: with `None`,
187	/// a set would prefer the device-local store and a get could not say which store answered.
188	#[cfg(not(test))]
189	fn synced_options(account: &str) -> PasswordOptions {
190	    let mut options = PasswordOptions::new_generic_password(SERVICE, account);
191	    options.set_access_synchronized(Some(true));
192	    options
193	}
