235	/// `errSecItemNotFound` — the Security framework's "no such item" status.
236	///
237	/// Callers that hold a raw `security_framework` error rather than a `KeychainError`
238	/// (a direct `ItemSearchOptions` query, for instance) compare against this instead of
239	/// re-spelling the magic number.
240	pub const ERR_SEC_ITEM_NOT_FOUND: i32 = -25300;
241	
242	/// Returns true if the error is errSecItemNotFound (OS status -25300).
243	/// Use this to distinguish "item does not exist" from transient OS errors.
244	pub fn is_not_found(err: &KeychainError) -> bool {
245	    match err {
246	        KeychainError::Security(e) => e.code() == ERR_SEC_ITEM_NOT_FOUND,
247	        // Not an absence claim — the account was never addressed.
248	        KeychainError::SyncNotPermitted { .. } => false,
249	        #[cfg(test)]
250	        KeychainError::NotFound => true,
251	    }
252	}
