254	// ── OAuth Keychain helpers ─────────────────────────────────────────────────────
255	
256	const DPOP_KEY_PRIV_ACCOUNT: &str = "oauth-dpop-key-priv";
257	const OAUTH_ACCESS_TOKEN_ACCOUNT: &str = "oauth-access-token";
258	const OAUTH_REFRESH_TOKEN_ACCOUNT: &str = "oauth-refresh-token";
259	const PDS_URL_ACCOUNT: &str = "relay-base-url";
260	const APPEARANCE_ACCOUNT: &str = "appearance-preference";
261	
262	/// Store the DPoP private key scalar (32 bytes) in the Keychain.
263	pub fn store_dpop_key(private_bytes: &[u8]) -> Result<(), KeychainError> {
264	    store_item(DPOP_KEY_PRIV_ACCOUNT, private_bytes)
265	}
266	
267	/// Load the DPoP private key scalar from the Keychain.
268	///
269	/// Returns `None` if no key has been stored yet (first run).
270	/// The returned bytes are wrapped in `Zeroizing` to ensure they are cleared on drop.
271	pub fn load_dpop_key() -> Option<zeroize::Zeroizing<[u8; 32]>> {
272	    match get_item(DPOP_KEY_PRIV_ACCOUNT) {
273	        Ok(bytes) if bytes.len() == 32 => {
274	            let mut arr = [0u8; 32];
275	            arr.copy_from_slice(&bytes);
276	            Some(zeroize::Zeroizing::new(arr))
277	        }
278	        Ok(_) => {
279	            tracing::warn!("DPoP key in Keychain has unexpected length; treating as absent");
280	            None
281	        }
282	        Err(e) if is_not_found(&e) => None,
283	        Err(e) => {
284	            tracing::error!(error = ?e, "Keychain error loading DPoP key");
285	            None
286	        }
287	    }
288	}
289	
290	/// Store the OAuth access token and refresh token in the Keychain.
291	pub fn store_oauth_tokens(access_token: &str, refresh_token: &str) -> Result<(), KeychainError> {
292	    store_item(OAUTH_ACCESS_TOKEN_ACCOUNT, access_token.as_bytes())?;
293	    store_item(OAUTH_REFRESH_TOKEN_ACCOUNT, refresh_token.as_bytes())?;
294	    Ok(())
295	}
296	
297	/// Load the OAuth access token and refresh token from the Keychain.
298	///
299	/// Returns `None` if either token is missing (not yet authenticated).
300	pub fn load_oauth_tokens() -> Option<(String, String)> {
301	    let access = match get_item(OAUTH_ACCESS_TOKEN_ACCOUNT) {
302	        Ok(b) => match String::from_utf8(b) {
303	            Ok(s) => s,
304	            Err(e) => {
305	                tracing::error!(error = ?e, "UTF-8 error decoding access token from Keychain");
306	                return None;
307	            }
308	        },
309	        Err(e) if is_not_found(&e) => return None,
310	        Err(e) => {
311	            tracing::error!(error = ?e, "Keychain error loading access token");
312	            return None;
313	        }
314	    };
315	    let refresh = match get_item(OAUTH_REFRESH_TOKEN_ACCOUNT) {
316	        Ok(b) => match String::from_utf8(b) {
317	            Ok(s) => s,
318	            Err(e) => {
319	                tracing::error!(error = ?e, "UTF-8 error decoding refresh token from Keychain");
320	                return None;
321	            }
322	        },
323	        Err(e) if is_not_found(&e) => return None,
324	        Err(e) => {
325	            tracing::error!(error = ?e, "Keychain error loading refresh token");
326	            return None;
327	        }
328	    };
329	    Some((access, refresh))
330	}
