398	/// Reset the in-memory Keychain to a clean state.
399	///
400	/// Call this at the start of every test that touches the Keychain so that
401	/// sequential tests sharing the same OS thread start with an empty store.
402	#[cfg(test)]
403	pub fn clear_for_test() {
404	    test_store::clear_all();
405	}
406	
407	/// In-memory Keychain substitute used exclusively in test builds.
408	///
409	/// Thread-local storage ensures tests on different threads are fully isolated.
410	/// Call `clear_for_test()` at the start of each test to handle sequential
411	/// reuse of the same OS thread by the Rust test harness.
412	///
413	/// Keys are `(scope, account)`, mirroring the real Keychain's two-store split: the same
414	/// account in `Local` and `Synced` is two independent records, and neither accessor family
415	/// can see the other's value. Tests that assert the launch backfill depend on that.
416	#[cfg(test)]
417	mod test_store {
418	    use std::cell::RefCell;
419	    use std::collections::HashMap;
420	
421	    /// Which of the two Keychain stores a call addresses.
422	    #[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
423	    pub enum Scope {
424	        /// The default, device-local store.
425	        Local,
426	        /// The `kSecAttrSynchronizable` (iCloud Keychain) store.
427	        Synced,
428	    }
429	
430	    thread_local! {
431	        static STORE: RefCell<HashMap<(Scope, String), Vec<u8>>> = RefCell::new(HashMap::new());
432	    }
433	
434	    pub fn get(scope: Scope, account: &str) -> Option<Vec<u8>> {
435	        STORE.with(|s| s.borrow().get(&(scope, account.to_string())).cloned())
436	    }
437	
438	    pub fn set(scope: Scope, account: &str, data: Vec<u8>) {
439	        STORE.with(|s| {
440	            s.borrow_mut().insert((scope, account.to_string()), data);
441	        });
442	    }
443	
444	    pub fn delete(scope: Scope, account: &str) {
445	        STORE.with(|s| {
446	            s.borrow_mut().remove(&(scope, account.to_string()));
447	        });
448	    }
449	
450	    pub fn clear_all() {
451	        STORE.with(|s| s.borrow_mut().clear());
452	    }
453	}
