455	#[cfg(test)]
456	mod tests {
457	    use super::*;
458	
459	    const DID: &str = "did:plc:REDACTED";
460	
461	    /// The tracked entitlements, embedded at compile time so this assertion cannot drift
462	    /// from the file that actually ships (`ios-postinit`'s Patch H installs this exact
463	    /// content into the generated project).
464	    const ENTITLEMENTS: &str = include_str!("../Entitlements.ios.plist");
465	
466	    /// The `<string>` values of the `keychain-access-groups` array, in declaration order.
467	    fn declared_access_groups() -> Vec<String> {
468	        let after_key = ENTITLEMENTS
469	            .split_once("<key>keychain-access-groups</key>")
470	            .expect("Entitlements.ios.plist declares no keychain-access-groups")
471	            .1;
472	        let array = after_key
473	            .split_once("<array>")
474	            .and_then(|(_, rest)| rest.split_once("</array>"))
475	            .expect("keychain-access-groups is not followed by an <array>")
476	            .0;
477	        array
478	            .split("<string>")
479	            .skip(1)
480	            .map(|entry| {
481	                entry
482	                    .split_once("</string>")
483	                    .expect("unterminated <string> in keychain-access-groups")
484	                    .0
485	                    .trim()
486	                    .to_string()
487	            })
488	            .collect()
489	    }
490	
491	    /// The entitlement's shape is the whole mechanism, and no Rust call site can observe it:
492	    /// the stable group must be FIRST (iOS writes new items to the first entitled group) and
493	    /// the legacy group must still be present (a read that names no group searches every
494	    /// entitled group, which is what keeps pre-rename items reachable). Dropping or
495	    /// reordering either entry orphans live identity material silently.
496	    #[test]
497	    fn entitlement_declares_stable_group_first() {
498	        let groups = declared_access_groups();
499	        assert_eq!(
500	            groups.first().map(String::as_str),
501	            Some(format!("$(AppIdentifierPrefix){STABLE_ACCESS_GROUP}").as_str()),
502	            "the stable group must be first — it is what makes it the write target; got {groups:?}"
503	        );
504	        assert!(
505	            groups.contains(&format!("$(AppIdentifierPrefix){LEGACY_ACCESS_GROUP}")),
506	            "the legacy group must stay declared or pre-rename items become unreachable; got {groups:?}"
507	        );
508	    }
509	
510	    /// The stable group must not track the bundle id — if it did, a rename would move it and
511	    /// the entitlement would be decoration.
512	    #[test]
513	    fn stable_group_is_not_the_bundle_id() {
514	        assert_ne!(STABLE_ACCESS_GROUP, LEGACY_ACCESS_GROUP);
515	        assert!(!ENTITLEMENTS.contains("$(CFBundleIdentifier)"));
516	    }
517	
518	    /// The allowlist admits exactly the per-DID Share 1 slot — not the bare prefix, and not
519	    /// the deprecated app-global `recovery-share-1` account (a pre-unification install's
520	    /// Share 1 is read from there but never written back into iCloud under that name).
521	    #[test]
522	    fn only_per_did_share1_syncs() {
523	        assert!(syncs_to_icloud(&crate::rekey::recovery_share1_account(DID)));
524	        assert!(!syncs_to_icloud("recovery-share-1"));
