1	// pattern: Imperative Shell
2	//
3	// The account-holder's notification endpoints:
4	//
5	//   POST   /v1/notifications/register               — register this device for push
6	//   DELETE /v1/notifications/register/{deviceUuid}  — stop pushing to this device
7	//   GET    /v1/notifications/sender-keys            — the set of keys to pin
8	//
9	// Auth is `auth::extractors::authenticate_access` (the DPoP-binding seam every access-token
10	// verification must route through — `just auth-seam-check` enforces it), so these live on
11	// the same-origin `/v1/*` surface alongside the other wallet endpoints.
12	//
13	// Registration keys on `(did, device_uuid)` rather than the `devices` table: `devices` rows
14	// are deleted inside the DID-promotion transaction, so a registration anchored there would
15	// die exactly when the account starts mattering. `device_uuid` is app-generated and stable
16	// across reinstalls of the same install identity.
17	//
18	// The relay round trip is deliberately **not** in the request path. Registration is one of
19	// the first calls the wallet makes after promotion; making it wait on a third-party relay
20	// would put that relay's uptime in the onboarding critical path for a feature whose entire
21	// failure mode is a missed banner. The row is stored, the relay registration is enqueued,
22	// and the response says plainly which of the two happened.
23	
24	use axum::{
25	    extract::{Path, State},
26	    http::{HeaderMap, Method, Uri},
27	    Json,
28	};
29	use serde::{Deserialize, Serialize};
30	
31	use crate::app::AppState;
32	use crate::auth::extractors::authenticate_access;
33	use crate::db::notifications as store;
34	use crate::notify_relay_client::{NotifyJob, RegistrationOwner};
35	use crate::routes::notification_views::{
36	    require_notifications_enabled, sender_keys_response, validate_registration_fields,
37	    SenderKeysResponse,
38	};
39	use common::{ApiError, ErrorCode};
40	
41	// ── POST /v1/notifications/register ───────────────────────────────────────────
42	
43	#[derive(Deserialize)]
44	#[serde(rename_all = "camelCase")]
45	pub struct RegisterRequest {
46	    /// App-generated stable device identifier. Survives DID promotion, unlike `devices.id`.
47	    pub device_uuid: String,
48	    /// The device's P-256 notification `did:key`. Payloads are sealed to this.
49	    pub notification_public_key: String,
50	    pub apns_token: String,
51	    pub apns_topic: String,
52	}
53	
54	#[derive(Serialize)]
55	#[serde(rename_all = "camelCase")]
56	pub struct RegisterResponse {
57	    /// Always `"pending"`: the row is stored, and the relay handle is being minted in the
58	    /// background. The app learns the outcome by re-reading, not by blocking here.
59	    pub status: &'static str,
60	}
61	
62	pub async fn register_notifications(
63	    State(state): State<AppState>,
64	    method: Method,
65	    uri: Uri,
66	    headers: HeaderMap,
67	    Json(payload): Json<RegisterRequest>,
68	) -> Result<Json<RegisterResponse>, ApiError> {
69	    let user = authenticate_access(&headers, &method, &uri, &state)?;
70	    require_notifications_enabled(&state)?;
71	
72	    if payload.device_uuid.is_empty() || payload.device_uuid.len() > MAX_DEVICE_UUID_LEN {
73	        return Err(ApiError::new(
74	            ErrorCode::InvalidRequest,
75	            "deviceUuid must be between 1 and 128 characters",
76	        ));
77	    }
78	    validate_registration_fields(
79	        &payload.notification_public_key,
80	        &payload.apns_token,
81	        &payload.apns_topic,
82	    )?;
83	
84	    store::upsert_registration(
85	        &state.db,
86	        &user.did,
87	        &payload.device_uuid,
88	        &payload.notification_public_key,
89	        &payload.apns_token,
90	        &payload.apns_topic,
91	    )
92	    .await
93	    .map_err(|e| {
94	        tracing::error!(error = %e, "failed to store a notification registration");
95	        ApiError::new(ErrorCode::InternalError, "failed to store the registration")
96	    })?;
97	
98	    if let Some(sender) = state.notify_sender.as_ref() {
99	        sender.send(NotifyJob::RegisterHandle {
100	            owner: RegistrationOwner::Account {
101	                did: user.did.clone(),
102	                device_uuid: payload.device_uuid.clone(),
103	            },
104	            apns_token: payload.apns_token,
105	            apns_topic: payload.apns_topic,
106	        });
107	    }
108	
109	    Ok(Json(RegisterResponse { status: "pending" }))
110	}
111	
112	const MAX_DEVICE_UUID_LEN: usize = 128;
113	
114	// ── DELETE /v1/notifications/register/{deviceUuid} ────────────────────────────
115	
116	#[derive(Serialize)]
117	#[serde(rename_all = "camelCase")]
118	pub struct UnregisterResponse {
119	    /// `"deleted"` when a registration existed, `"absent"` when there was nothing to remove.
120	    pub status: &'static str,
121	}
122	
123	pub async fn unregister_notifications(
124	    State(state): State<AppState>,
125	    method: Method,
126	    uri: Uri,
127	    headers: HeaderMap,
128	    Path(device_uuid): Path<String>,
129	) -> Result<Json<UnregisterResponse>, ApiError> {
130	    let user = authenticate_access(&headers, &method, &uri, &state)?;
131	
132	    // Deliberately *not* gated on `require_notifications_enabled`, unlike register and
133	    // sender-keys. An operator who removes the relay config leaves registrations behind; the
134	    // one thing a device should still be able to do is disown its own row and have the relay
135	    // told to drop the handle. Gating this would strand exactly the rows most worth removing.
136	
137	    // Read the row before deleting so the relay handle can be dropped too — otherwise the
138	    // relay keeps forwarding to a device this account has explicitly disowned.
139	    let handle = store::list_registrations(&state.db, &user.did)
140	        .await
141	        .ok()
142	        .and_then(|rows| {
143	            rows.into_iter()
144	                .find(|r| r.device_id == device_uuid)
145	                .and_then(|r| r.push_handle)
146	        });
147	
148	    let existed = store::delete_registration(&state.db, &user.did, &device_uuid)
149	        .await
150	        .map_err(|e| {
151	            tracing::error!(error = %e, "failed to delete a notification registration");
152	            ApiError::new(
153	                ErrorCode::InternalError,
154	                "failed to delete the registration",
155	            )
156	        })?;
157	
158	    if let (Some(handle), Some(sender)) = (handle, state.notify_sender.as_ref()) {
159	        sender.send(NotifyJob::DropHandle { handle });
160	    }
161	
162	    Ok(Json(UnregisterResponse {
163	        // Idempotent: repeating a delete is a 200, not a 404. The app retries this on a flaky
164	        // network and must not have to distinguish "already gone" from "failed".
165	        status: if existed { "deleted" } else { "absent" },
166	    }))
167	}
168	
169	// ── GET /v1/notifications/sender-keys ─────────────────────────────────────────
170	
171	/// The account-holder's re-pin surface. The published set itself is built by
172	/// [`notification_views::sender_keys_response`], which the operator surface shares — the
173	/// sender keys belong to the instance, not to whoever is asking.
174	pub async fn get_sender_keys(
175	    State(state): State<AppState>,
176	    method: Method,
177	    uri: Uri,
178	    headers: HeaderMap,
179	) -> Result<Json<SenderKeysResponse>, ApiError> {
180	    authenticate_access(&headers, &method, &uri, &state)?;
181	    require_notifications_enabled(&state)?;
182	    Ok(Json(sender_keys_response(&state).await?))
183	}
