487	            state.clone(),
488	            Request::get("/v1/notifications/sender-keys")
489	                .header("authorization", auth)
490	                .body(Body::empty())
491	                .unwrap(),
492	        )
493	        .await;
494	        assert_eq!(status, StatusCode::OK, "{body}");
495	
496	        let kids: Vec<i64> = body["keys"]
497	            .as_array()
498	            .unwrap()
499	            .iter()
500	            .map(|k| k["kid"].as_i64().unwrap())
501	            .collect();
502	        assert_eq!(
503	            kids,
504	            vec![active, retired],
505	            "revoked must be gone; retired must remain"
506	        );
507	
508	        // Every published key is a usable P-256 did:key, not an opaque string.
509	        for key in body["keys"].as_array().unwrap() {
510	            crypto::p256_public_key_from_did_key(key["publicKey"].as_str().unwrap())
511	                .expect("published key must decode");
512	        }
513	    }
514	
515	    /// A relay configured without a master key cannot mint or unwrap sender keys. It must say
516	    /// so, rather than answer 200 with an empty set — a client that pinned nothing would then
517	    /// fail to verify every notification it received, with no way to tell why.
518	    #[tokio::test]
519	    async fn a_configured_instance_without_a_master_key_refuses_to_publish_an_empty_set() {
520	        let mut state = state_with_notifications().await;
521	        let mut config = (*state.config).clone();
522	        config.signing_key_master_key = None;
523	        state.config = Arc::new(config);
524	        seed_account(&state, "did:plc:notifroutes").await;
525	
526	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
527	        let (status, body) = call(
528	            state.clone(),
529	            Request::get("/v1/notifications/sender-keys")
530	                .header("authorization", auth)
531	                .body(Body::empty())
532	                .unwrap(),
533	        )
534	        .await;
535	
536	        // 503, not the 501 an unconfigured instance returns: the operator *has* opted in, the
537	        // instance simply cannot serve the keys right now.
538	        assert_eq!(status, StatusCode::SERVICE_UNAVAILABLE, "{body}");
539	        assert!(
540	            body["error"]["message"]
541	                .as_str()
542	                .unwrap_or_default()
543	                .contains("master key"),
544	            "the error must name the missing master key: {body}"
545	        );
546	    }
547	
548	    /// The other route to an empty set: the master key is present, but the stored key material
549	    /// will not decrypt under it (a restored backup wrapped under a previous KEK, say). The
550	    /// client must be told, not handed an empty array it would pin as authoritative.
551	    #[tokio::test]
552	    async fn a_stored_key_that_will_not_unwrap_is_reported_rather_than_silently_dropped() {
553	        let state = state_with_notifications().await;
554	        seed_account(&state, "did:plc:notifroutes").await;
555	
556	        // Ciphertext that is well-formed base64 but not decryptable under this master key —
557	        // exactly what a KEK mismatch leaves behind.
558	        store::insert_sender_key(&state.db, "bm90LWEtcmVhbC1jaXBoZXJ0ZXh0LWF0LWFsbA")
559	            .await
560	            .unwrap();
561	
562	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
563	        let (status, body) = call(
564	            state.clone(),
565	            Request::get("/v1/notifications/sender-keys")
566	                .header("authorization", auth)
567	                .body(Body::empty())
568	                .unwrap(),
569	        )
570	        .await;
571	
572	        assert_eq!(
573	            status,
574	            StatusCode::SERVICE_UNAVAILABLE,
575	            "an unusable key set must not be served as an empty one: {body}"
576	        );
577	        assert!(
578	            body["keys"].is_null(),
579	            "no key array should be returned: {body}"
580	        );
581	    }
582	
583	    /// An app that fetches the set before the instance has ever sent anything must still get
584	    /// a key to pin — otherwise it cannot verify the very first notification it receives.
585	    #[tokio::test]
586	    async fn the_first_fetch_mints_the_instances_first_sender_key() {
587	        let state = state_with_notifications().await;
588	        seed_account(&state, "did:plc:notifroutes").await;
589	
590	        let auth = format!("Bearer {}", token(&state, "did:plc:notifroutes"));
591	        let (status, body) = call(
592	            state.clone(),
593	            Request::get("/v1/notifications/sender-keys")
594	                .header("authorization", auth)
595	                .body(Body::empty())
596	                .unwrap(),
597	        )
598	        .await;
599	        assert_eq!(status, StatusCode::OK);
600	        assert_eq!(body["keys"].as_array().unwrap().len(), 1);
601	    }
602	}
