1	// pattern: Imperative Shell
2	//
3	// Shared, handler-free support for the two notification surfaces — the account-holder's
4	// (`notifications.rs`) and the operator's (`admin_notifications.rs`). Routes may not import
5	// one another, so everything both need lives here: the registration field validators and the
6	// `sender-keys` response shape.
7	//
8	// Same non-handler-support-file pattern as `admin_subject_defs.rs` and `oauth_templates.rs`.
9	
10	use serde::Serialize;
11	
12	use crate::app::AppState;
13	use crate::auth::validation::validate_device_public_key;
14	use common::{ApiError, ErrorCode};
15	
16	/// Reject when the operator has not configured a relay.
17	///
18	/// A 501 rather than a 404: the route exists, this instance has simply not opted into push.
19	/// A client reads that as "notifications unavailable here" and stops asking — the honest
20	/// answer for a self-hoster who never pointed at a relay.
21	pub(crate) fn require_notifications_enabled(state: &AppState) -> Result<(), ApiError> {
22	    if state.config.notifications.relay.is_none() {
23	        return Err(ApiError::new(
24	            ErrorCode::MethodNotImplemented,
25	            "this instance is not configured for push notifications",
26	        ));
27	    }
28	    Ok(())
29	}
30	
31	/// Bound on an APNs device token / topic. Both are echoed to Apple by the relay.
32	const MAX_APNS_FIELD_LEN: usize = 200;
33	
34	/// Validate everything a registration body carries, on both surfaces.
35	///
36	/// The public key is decoded, not merely length-checked: a key we cannot decode now is a
37	/// device we cannot reach later, and that failure would surface only at send time, far from
38	/// the request that caused it.
39	pub(crate) fn validate_registration_fields(
40	    notification_public_key: &str,
41	    apns_token: &str,
42	    apns_topic: &str,
43	) -> Result<(), ApiError> {
44	    let invalid = |msg: String| ApiError::new(ErrorCode::InvalidRequest, msg);
45	
46	    validate_device_public_key(notification_public_key)
47	        .map_err(|e| invalid(e.replace("devicePublicKey", "notificationPublicKey")))?;
48	    crypto::p256_public_key_from_did_key(notification_public_key).map_err(|e| {
49	        invalid(format!(
50	            "notificationPublicKey must be a P-256 did:key ({e})"
51	        ))
52	    })?;
53	
54	    if apns_token.is_empty() || apns_token.len() > MAX_APNS_FIELD_LEN {
55	        return Err(invalid(format!(
56	            "apnsToken must be between 1 and {MAX_APNS_FIELD_LEN} characters"
57	        )));
58	    }
59	    if !apns_token.bytes().all(|b| b.is_ascii_hexdigit()) {
60	        return Err(invalid("apnsToken must be hexadecimal".to_string()));
61	    }
62	    if apns_topic.is_empty() || apns_topic.len() > MAX_APNS_FIELD_LEN {
63	        return Err(invalid(format!(
64	            "apnsTopic must be between 1 and {MAX_APNS_FIELD_LEN} characters"
65	        )));
66	    }
67	    if !apns_topic
68	        .bytes()
69	        .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-')
70	    {
71	        return Err(invalid("apnsTopic must be a bundle identifier".to_string()));
72	    }
73	    Ok(())
74	}
75	
76	#[derive(Serialize)]
77	#[serde(rename_all = "camelCase")]
78	pub struct SenderKey {
79	    /// Version. Every sealed payload's envelope names which key sealed it.
80	    pub kid: i64,
81	    /// The P-256 `did:key` to verify against.
82	    pub public_key: String,
83	}
84	
85	#[derive(Serialize)]
86	#[serde(rename_all = "camelCase")]
87	pub struct SenderKeysResponse {
88	    pub keys: Vec<SenderKey>,
89	}
90	
91	/// The published sender-key set — a property of the instance, not of who is asking, so both
92	/// surfaces serve exactly this.
93	///
94	/// This is the re-pin surface: clients fetch it on every successful Custos contact, which is
95	/// what keeps the compromise window short. Revocation drops a key from the set immediately,
96	/// and the next contact is the last time a device will trust it. Retired keys stay, because a
97	/// payload sealed just before a rotation must still verify on a device that has re-pinned.
98	pub(crate) async fn sender_keys_response(state: &AppState) -> Result<SenderKeysResponse, ApiError> {
99	    let keys = crate::notifications::published_sender_keys(state)
100	        .await
101	        .map_err(|e| {
102	            tracing::error!(error = %e, "failed to load notification sender keys");
103	            match e {
104	                // Distinct from the 501 above: the operator *has* opted into notifications,
105	                // but the instance cannot mint or unwrap the keys that make them verifiable.
106	                // A 503 says "configured but not currently able", which is the truth, and
107	                // keeps a client from pinning an empty set and silently trusting nothing.
108	                crate::notifications::SenderKeyError::NoMasterKey => ApiError::new(
109	                    ErrorCode::ServiceUnavailable,
110	                    "notifications are configured but the signing-key master key is not set",
111	                ),
112	                crate::notifications::SenderKeyError::NoUsableKey => ApiError::new(
113	                    ErrorCode::ServiceUnavailable,
114	                    "no usable notification sender key is available",
115	                ),
116	                crate::notifications::SenderKeyError::Db(_) => {
117	                    ApiError::new(ErrorCode::InternalError, "failed to load sender keys")
118	                }
119	            }
120	        })?;
121	
122	    Ok(SenderKeysResponse {
123	        keys: keys
124	            .into_iter()
125	            .map(|(kid, public_key)| SenderKey { kid, public_key })
126	            .collect(),
127	    })
128	}
