1	// pattern: Mixed (Functional Core error mapping; Imperative Shell commands)
2	//
3	// App-password management for a wallet-custodied identity — the surface that signs
4	// the official Bluesky app (and other password-login clients) into a passwordless
5	// sovereign Custos account. Three Tauri IPC commands:
6	//
7	//   create_app_password(did, name, privileged) — mint; returns the secret ONCE
8	//   list_app_passwords(did)                    — metadata only, never the secret
9	//   revoke_app_password(did, name)             — kills the credential and its sessions
10	//
11	// A sovereign account has no main password, so the PDS's createSession app-password
12	// fallback (V031) makes this minted credential the only way a password-login client
13	// can open a session — and that session is scope-bounded (`com.atproto.appPass`):
14	// it can post/like/follow and proxy to the AppView, but can never touch account
15	// management, PLC/identity ops, agent surfaces, or app-password management itself.
16	// Chat (DMs) additionally requires the `privileged` flag chosen at mint time.
17	//
18	// Every command resolves a per-DID full-access session through
19	// `SessionProvider::full_access_client` (the mint/list/revoke routes require full
20	// access — an app password cannot manage app passwords). A `NeedsUnlock` maps to
21	// `SESSION_LOCKED`, the frontend's cue to run the biometric `sovereignLogin(did)`
22	// and retry, exactly like the change-handle flow. The biometric gate on minting
23	// lives in the frontend wrapper (`$lib/ipc/app-passwords.ts`), in front of this.
24	
25	use serde::Serialize;
26	
27	use crate::identity_store::IdentityStore;
28	use crate::pds_client::{self, AppPasswordCreated, AppPasswordEntry, PdsClient, PdsClientError};
29	use crate::session_provider::{SessionError, SessionProvider, UnlockReason};
30	
31	// ── Errors ───────────────────────────────────────────────────────────────────
32	
33	/// Errors from the app-password management commands.
34	///
35	/// Serializes as `{ "code": "SCREAMING_SNAKE_CASE", ... }` to match the sibling
36	/// wallet error enums (`HandleChangeError`, `AgentsError`, `SessionError`).
37	#[derive(Debug, Serialize, thiserror::Error)]
38	#[serde(
39	    tag = "code",
40	    rename_all = "SCREAMING_SNAKE_CASE",
41	    rename_all_fields = "camelCase"
42	)]
43	pub enum AppPasswordsError {
44	    /// The identity's session could not be resolved without a passwordless unlock —
45	    /// the frontend should run the biometric sovereign login and retry.
46	    #[error("identity is locked and needs a passwordless unlock")]
47	    SessionLocked { reason: UnlockReason },
48	    /// The hosting PDS rate limited the request.
49	    #[error("rate limited")]
50	    RateLimited { retry_after: Option<String> },
51	    /// An app password with this name already exists on the account.
52	    #[error("an app password with this name already exists")]
53	    DuplicateName,
54	    /// The DID is not registered in this wallet.
55	    #[error("identity not found: {message}")]
56	    IdentityNotFound { message: String },
57	    /// A server-side step failed for a non-connectivity reason: the hosting PDS refused
58	    /// the request (non-2xx other than the cases above, `status` carries the HTTP code),
59	    /// or the session could not be resolved for a reason that is not a transport failure
60	    /// (refresh verdict, unsupported host, malformed response, or local session storage —
61	    /// `status` is `None` for these).
62	    #[error("server error: {message}")]
63	    ServerError {
64	        status: Option<u16>,
65	        message: String,
66	    },
67	    /// A network / transport call failed.
68	    #[error("network error: {message}")]
69	    NetworkError { message: String },
70	}
71	
72	/// Map a session-lifecycle failure into the app-password surface. Exhaustive on purpose: only
73	/// a genuine transport failure becomes `NetworkError` — a server verdict, unsupported host, or
74	/// storage failure must not surface as "check your connection", or the real cause becomes
75	/// undiagnosable from the screen (the same defect class `classify_xrpc_error` exists to fix).
76	fn map_session_error(error: SessionError) -> AppPasswordsError {
77	    match error {
78	        SessionError::NeedsUnlock { reason } => AppPasswordsError::SessionLocked { reason },
79	        SessionError::RateLimited { retry_after } => AppPasswordsError::RateLimited { retry_after },
80	        SessionError::IdentityNotFound => AppPasswordsError::IdentityNotFound {
81	            message: "identity not found".to_string(),
82	        },
83	        SessionError::Offline { message } => AppPasswordsError::NetworkError { message },
84	        SessionError::ServerFailure { status } => AppPasswordsError::ServerError {
85	            status: Some(status),
86	            message: format!("session request failed with status {status}"),
87	        },
88	        SessionError::UnsupportedHost => AppPasswordsError::ServerError {
89	            status: None,
90	            message: "the identity's hosting server does not support session refresh".to_string(),
91	        },
92	        SessionError::Keychain { message } => AppPasswordsError::ServerError {
93	            status: None,
94	            message: format!("session keychain failure: {message}"),
95	        },
96	        SessionError::InvalidResponse { message } => AppPasswordsError::ServerError {
97	            status: None,
98	            message: format!("invalid session response: {message}"),
99	        },
100	    }
101	}
102	
103	/// Map a classified XRPC failure into the app-password surface. The one
104	/// status-specific case is 409 → `DuplicateName` (the createAppPassword conflict);
105	/// every other server refusal keeps its status + message so the UI can show the
106	/// real reason instead of connectivity boilerplate.
107	fn map_pds_error(error: PdsClientError) -> AppPasswordsError {
108	    match error {
109	        PdsClientError::RateLimited { retry_after, .. } => {
110	            AppPasswordsError::RateLimited { retry_after }
111	        }
112	        PdsClientError::XrpcError { status: 409, .. } => AppPasswordsError::DuplicateName,
113	        PdsClientError::XrpcError {
114	            status, message, ..
115	        } => AppPasswordsError::ServerError {
116	            status: Some(status),
117	            message,
118	        },
119	        PdsClientError::Unauthorized { message, .. } => AppPasswordsError::ServerError {
120	            status: Some(401),
121	            message,
122	        },
123	        PdsClientError::NetworkError { message } => AppPasswordsError::NetworkError { message },
124	        other => AppPasswordsError::NetworkError {
125	            message: other.to_string(),
126	        },
127	    }
128	}
129	
130	/// Resolve the DID's full-access session (restore / refresh, or `SessionLocked`).
131	async fn full_access_session(
132	    pds_client: &PdsClient,
133	    did: &str,
134	) -> Result<crate::session_provider::ActiveSession, AppPasswordsError> {
135	    let now = crate::sovereign_session::unix_timestamp().map_err(|_| {
136	        AppPasswordsError::NetworkError {
137	            message: "system clock is unavailable".to_string(),
138	        }
139	    })?;
140	    SessionProvider
141	        .full_access_client(pds_client, &IdentityStore, did, now)
142	        .await
143	        .map_err(map_session_error)
144	}
145	
146	// ── Tauri commands ───────────────────────────────────────────────────────────
147	
148	/// Tauri command: mint a named app password for the identity. Returns the generated
149	/// secret ONCE — it is never retrievable again. The frontend gates this behind
150	/// `authenticateBiometric()` (it creates a durable login credential).
151	#[tauri::command]
152	pub async fn create_app_password(
153	    state: tauri::State<'_, crate::oauth::AppState>,
154	    did: String,
155	    name: String,
156	    privileged: bool,
157	) -> Result<AppPasswordCreated, AppPasswordsError> {
158	    let session = full_access_session(state.pds_client(), &did).await?;
159	    pds_client::create_app_password(&session.client, &name, privileged)
160	        .await
161	        .map_err(map_pds_error)
162	}
163	
164	/// Tauri command: list the identity's app passwords (metadata only, never secrets).
165	#[tauri::command]
166	pub async fn list_app_passwords(
167	    state: tauri::State<'_, crate::oauth::AppState>,
168	    did: String,
169	) -> Result<Vec<AppPasswordEntry>, AppPasswordsError> {
170	    let session = full_access_session(state.pds_client(), &did).await?;
171	    pds_client::list_app_passwords(&session.client)
172	        .await
173	        .map_err(map_pds_error)
174	}
175	
176	/// Tauri command: revoke a named app password. The server deletes the credential and
177	/// its sessions/refresh tokens atomically, so a signed-in client is cut off at once.
178	#[tauri::command]
179	pub async fn revoke_app_password(
180	    state: tauri::State<'_, crate::oauth::AppState>,
181	    did: String,
182	    name: String,
183	) -> Result<(), AppPasswordsError> {
184	    let session = full_access_session(state.pds_client(), &did).await?;
185	    pds_client::revoke_app_password(&session.client, &name)
186	        .await
187	        .map_err(map_pds_error)
188	}
