        ));
        assert!(matches!(
            map_session_error(SessionError::ServerFailure { status: 503 }),
            NotificationsError::ServerError {
                status: Some(503),
                ..
            }
        ));
        assert!(matches!(
            map_session_error(SessionError::UnsupportedHost),
            NotificationsError::ServerError { status: None, .. }
        ));
